INSERT INTO public.films VALUES (502, 'tt1392190', 'Mad Max: Fury Road', 2015, 'George Miller', '120 min', 'In a post-apocalyptic wasteland, a woman rebels against a tyrannical ruler in search for her homeland with the aid of a group of female prisoners, a psychotic worshipper and a drifter named Max.', 'https://m.media-amazon.com/images/M/MV5BZDRkODJhOTgtOTc1OC00NTgzLTk4NjItNDgxZDY4YjlmNDY2XkEyXkFqcGc@._V1_SX300.jpg', 'Action, Adventure, Sci-Fi', 8.1) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (503, 'tt1385826', 'The Adjustment Bureau', 2011, 'George Nolfi', '106 min', 'The relationship between a politician and a contemporary dancer is affected by mysterious forces keeping them apart.', 'https://m.media-amazon.com/images/M/MV5BMTU3ODg3MDAxMl5BMl5BanBnXkFtZTcwMjc0MDMzNA@@._V1_SX300.jpg', 'Crime, Drama, Mystery', 7.0) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (504, 'tt1371111', 'Cloud Atlas', 2012, 'Tom Tykwer, Lana Wachowski, Lilly Wachowski', '172 min', 'As souls are born and reborn, they renew their connections to one another throughout the ages.', 'https://m.media-amazon.com/images/M/MV5BMTczMTgxMjc4NF5BMl5BanBnXkFtZTcwNjM5MTA2OA@@._V1_SX300.jpg', 'Drama, Mystery, Sci-Fi', 7.3) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (506, 'tt1259571', 'The Twilight Saga: New Moon', 2009, 'Chris Weitz', '130 min', 'After Edward leaves because of an incident involving Bella, Jacob Black becomes her best friend, but what Bella doesn''t realize is that Jacob also has a secret that will suddenly change their lives.', 'https://m.media-amazon.com/images/M/MV5BMTI3MjE3NDIxNF5BMl5BanBnXkFtZTcwODM3NTY5Mg@@._V1_SX300.jpg', 'Adventure, Drama, Fantasy', 4.8) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (507, 'tt1228705', 'Iron Man 2', 2010, 'Jon Favreau', '124 min', 'With the world now aware of his identity as Iron Man, Tony Stark must contend with both his declining health and a vengeful mad man with ties to his father''s legacy.', 'https://m.media-amazon.com/images/M/MV5BYWYyOGQzOGYtMGQ1My00ZWYxLTgzZjktZWYzN2IwYjkxYzM0XkEyXkFqcGc@._V1_SX300.jpg', 'Action, Sci-Fi', 6.9) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (508, 'tt1210166', 'Moneyball', 2011, 'Bennett Miller', '133 min', 'Oakland A''s general manager Billy Beane''s successful attempt to assemble a baseball team on a lean budget by employing computer-generated analysis to acquire new players.', 'https://m.media-amazon.com/images/M/MV5BMjAxOTU3Mzc1M15BMl5BanBnXkFtZTcwMzk1ODUzNg@@._V1_SX300.jpg', 'Biography, Drama, Sport', 7.6) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (281, 'tt1201607', 'Harry Potter and the Deathly Hallows: Part 2', 2011, 'David Yates', '130 min', 'Harry, Ron and Hermione set out on a quest to eliminate the remaining horcruxes. On the other hand, the students and teachers must unite to defend Hogwarts against Lord Voldemort and his army.', 'https://m.media-amazon.com/images/M/MV5BOTA1Mzc2N2ItZWRiNS00MjQzLTlmZDQtMjU0NmY1YWRkMGQ4XkEyXkFqcGc@._V1_SX300.jpg', 'Adventure, Family, Fantasy', 8.1) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (510, 'tt1179933', '10 Cloverfield Lane', 2016, 'Dan Trachtenberg', '103 min', 'A young woman is held in an underground bunker by a man who insists that a hostile event has left the surface of the Earth uninhabitable.', 'https://m.media-amazon.com/images/M/MV5BMjEzMjczOTIxMV5BMl5BanBnXkFtZTgwOTUwMjI3NzE@._V1_SX300.jpg', 'Drama, Horror, Sci-Fi', 7.2) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (512, 'tt1155592', 'Man on Wire', 2008, 'James Marsh', '94 min', 'A look at tightrope walker Philippe Petit''s daring, but illegal, high-wire routine performed between New York City''s World Trade Center''s twin towers in 1974, what some consider, "the artistic crime of the century".', 'https://m.media-amazon.com/images/M/MV5BMTMxNTk3NDY1NV5BMl5BanBnXkFtZTcwNDk0ODg3MQ@@._V1_SX300.jpg', 'Documentary, Biography, Crime', 7.7) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (515, 'tt1045658', 'Silver Linings Playbook', 2012, 'David O. Russell', '122 min', 'After a stint in a mental institution, former teacher Pat Solitano moves back in with his parents and tries to reconcile with his ex-wife. Things get more challenging when Pat meets Tiffany, a mysterious girl with problems of her ...', 'https://m.media-amazon.com/images/M/MV5BMTM2MTI5NzA3MF5BMl5BanBnXkFtZTcwODExNTc0OA@@._V1_SX300.jpg', 'Comedy, Drama, Romance', 7.7) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (518, 'tt0947798', 'Black Swan', 2010, 'Darren Aronofsky', '108 min', 'Nina is a talented but unstable ballerina on the verge of stardom. Pushed to the breaking point by her artistic director and a seductive rival, Nina''s grip on reality slips, plunging her into a waking nightmare.', 'https://m.media-amazon.com/images/M/MV5BNzY2NzI4OTE5MF5BMl5BanBnXkFtZTcwMjMyNDY4Mw@@._V1_SX300.jpg', 'Drama, Thriller', 8.0) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (522, 'tt0840361', 'The Town', 2010, 'Ben Affleck', '125 min', 'A proficient group of thieves rob a bank and hold the manager hostage. Things begin to get complicated when one of the crew members falls in love with her.', 'https://m.media-amazon.com/images/M/MV5BMTcyNzcxODg3Nl5BMl5BanBnXkFtZTcwMTUyNjQ3Mw@@._V1_SX300.jpg', 'Crime, Drama, Thriller', 7.5) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (306, 'tt0421715', 'The Curious Case of Benjamin Button', 2008, 'David Fincher', '166 min', 'Benjamin Button, born in 1918 with the physical state of an elderly man, ages in reverse. He experiences love and break-ups, ecstasy and sorrow, and timelessness by the time he dies in 2003 as a baby.', 'https://m.media-amazon.com/images/M/MV5BYjIyNDExOWItM2Y4ZC00NmY3LWFlN2ItYTJlZDQ1NTJlZTUwXkEyXkFqcGc@._V1_SX300.jpg', 'Drama, Fantasy, Romance', 7.8) ON CONFLICT DO NOTHING;
INSERT INTO public.films VALUES (329, 'tt0240772', 'Ocean''s Eleven', 2001, 'Steven Soderbergh', '116 min', 'Danny Ocean, a gangster, rounds up a gang of associates to stage a sophisticated and elaborate casino heist which involves robbing three Las Vegas casinos simultaneously during a popular boxing event.', 'https://m.media-amazon.com/images/M/MV5BMmNhZDkxYTgtMDM3ZC00NTQ3LWFjZTUtNzc1Y2QyNWZjNDRmXkEyXkFqcGc@._V1_SX300.jpg', 'Crime, Thriller', 7.7) ON CONFLICT DO NOTHING;
